css:
.tour-container {
  font-family: Arial, sans-serif;
  color: #222;
  margin: 0 40px;
}

.header {
  border-bottom: 1px solid #e0e0e0;
  text-align: center;
  padding: 20px 0;
}

.logo {
  height: 5rem;
  margin-bottom: 10px;
}

.title {
  text-align: center;
  font-size: 24px;
  font-weight: 500;
  margin-top: 24px;
  line-height: 1.5;
}
.sub-container {
  text-align: center;
  width: 100%;
}

.subtitle {
  display: inline-block;
  text-align: center;
  color: #555;
  max-width: 700px;
  line-height: 1.5;
}

.summary {
  display: flex;
  width: 100%;
  justify-content: space-between;
  gap: 16px;
  margin: 30px 0;
}

.summary-box {
  border: 1px solid #ddd;
  width: 23%;
  border-radius: 6px;
  text-align: center;
  padding: 16px;
}

.summary-box .label {
  font-size: 14px;
  color: #666;
  border: none;
}

.summary-box .value {
  font-size: 20px;
  margin-top: 8px;
  font-weight: 500;
}

.day-card {
  border: 1px solid #ddd;
  width: 100%;
  border-radius: 6px;
  margin: 40px 0;
  overflow: hidden;
  page-break-inside: avoid;
}
.accomodation-card {
  width: 100%;
  margin: 40px 0;
  overflow: hidden;
  page-break-inside: avoid;
}

.day-image {
  width: 100%;
  height: 320px;
  object-fit: cover;
}

.day-content {
  box-sizing: border-box;
  padding: 24px;
}

.day-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.day-label {
  background: #030213;
  color: white;
  padding: 8px 12px;
  border-radius: 4px;
  font-weight: 500;
}

.difficulty {
  background: #c8f7c5;
  color: #0c5b0c;
  font-size: 14px;
  border-radius: 20px;
  padding: 4px 10px;
}

.day-title {
  font-size: 22px;
  margin-top: 20px;
}

.destination {
  margin-top: 20px;
}

.destination-header {
  display: flex;
  align-items: center;
  gap: 10px;
}

.destination h3 {
  margin: 0;
  margin-left: 10px;
  font-weight: 500;
  font-size: 16px;
}

.destination p {
  color: #555;
  margin-top: 6px;
}

.notes {
  background: #f2f2f2;
  padding: 16px;
  border-radius: 8px;
  margin-top: 20px;
}

.notes-header {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 8px;
}
.notes h4 {
  margin: 0;
  margin-left: 10px;
  font-weight: 500;
  font-size: 16px;
}

.notes ul {
  margin: 0;
  padding-left: 18px;
}
.notes ul li {
  color: #444;
  font-size: 14px;
}

.attractions {
  margin-top: 20px;
}

.attractions h4 {
  margin-bottom: 10px;
}

.attractions-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}

.chip {
  background: #f0f0f0;
  padding: 6px 10px;
  border-radius: 6px;
  font-size: 14px;
}

.chip span {
  color: #666;
  margin-left: 4px;
}

.activities {
  margin-top: 20px;
}
.activities h4 {
  margin: 0;
  font-weight: 500;
  margin-bottom: 10px;
  font-size: 16px;
}

.activities-grid {
  width: 100%;
  font-size: 0; /* remove inline-block spacing */
}

.activity-item {
  display: inline-block;
  width: 49%; /* two items per row */
  vertical-align: top;
  font-size: 14px; /* restore font size */
  margin-right: 2%; /* gap between items */
  margin-bottom: 10px; /* gap between rows */
}

.activity-item:nth-child(2n) {
  margin-right: 0; /* remove right margin for every second item */
}

.activity-name {
  font-weight: 600;
  color: #0a0a0a;
}

.activity-desc {
  font-size: 14px;
  color: #666;
  margin-top: 4px;
}

.travel {
  border-top: 1px solid #e0e0e0;
  margin-top: 20px;
  padding-top: 20px;
}
.travel h4 {
  margin: 0;
  font-weight: 400;
  margin-bottom: 10px;
  font-size: 16px;
}

.travel-grid {
  display: flex;
  justify-content: space-between;
}

.travel-item {
  display: flex;
  /* align-items: center; */
}
.travel-desc {
  width: 100%;
  margin-left: 10px;
}
.label-box {
  font-weight: 600;
  color: #555;
  font-size: 12px;
  background: #fdfdfd;
  margin-bottom: 0px;
}
.value {
  font-size: 14px;
  color: #000;
  font-weight: 400;
}

table {
  border-collapse: collapse;
  width: 100%;
  font-family: Arial, sans-serif;
  font-size: 14px;
}

td {
  border: 1px solid #000;
  padding: 6px 10px;
  vertical-align: middle;
}

td:first-child {
  font-weight: bold;
}

td:last-child {
  text-align: right;
}
